SELECT order_id, AVG(CAST(product_quantity AS REAL)) - (SELECT AVG(CAST(product_quantity AS REAL)) FROM Order_Items) AS difference FROM Order_Items GROUP BY order_id
WITH order_avgs AS (
  SELECT order_id, AVG(CAST(product_quantity AS REAL)) AS order_average
  FROM Order_Items
  GROUP BY order_id
)
SELECT order_id,
       order_average,
       order_average - (SELECT AVG(order_average) FROM order_avgs) AS difference
FROM order_avgs;
SELECT AVG(CAST(product_quantity AS REAL)) FROM Order_Items;
SELECT AVG(product_quantity) FROM Order_Items;
